Dropzone.autoDiscover = false;

$(document).ready(function () {
    let form = $("#per-diem-network-form, #per-diem-network-form-update");
    if (form.length === 0) return;

    let uploadUrl = form.data('upload-url');
    let csrfToken = form.data('csrf-token');
    let csrfHash = form.data('csrf-hash');
    let baseUrl = form.data('base-url');

    let logoDropzone = new Dropzone("#logo-dropzone", {
        url: uploadUrl,
        paramName: "file",
        maxFiles: 1,
        acceptedFiles: "image/*",
        autoProcessQueue: false,
        headers: {
            'X-Requested-With': 'XMLHttpRequest'
        },
        init: function () {
            this.on("sending", function (file, xhr, formData) {
                formData.append(csrfToken, csrfHash);
                formData.append("type", "logo");
            });

            this.on("success", function (file, response) {
                if (response.status === 'success') {
                    $("#logo_path").val(response.path);
                }
            });

            this.on("addedfile", function () {
                if (this.files[1] != null) {
                    this.removeFile(this.files[0]);
                }
            });

            this.on("queuecomplete", function () {
                if (isSubmitting) {
                    submitFormData();
                }
            });

            // If editing, show the current logo
            let currentPath = $("#logo_path").val();
            if (currentPath && currentPath.trim() !== "") {
                let mockFile = { name: "Current Logo", size: 12345, accepted: true };
                this.emit("addedfile", mockFile);
                this.emit("thumbnail", mockFile, baseUrl + (currentPath.startsWith('/') ? currentPath : '/' + currentPath));
                this.emit("complete", mockFile);
                this.files.push(mockFile);
            }
        }
    });

    let isSubmitting = false;

    function submitFormData() {
        if (!isSubmitting) return;

        let btn = $("#submit-btn, #submit-btn-update");
        let isUpdate = form.attr('action').indexOf('update') !== -1;
        
        btn.text(isUpdate ? "Updating Network..." : "Saving Network...");

        $.ajax({
            url: form.attr('action'),
            method: 'POST',
            data: form.serialize(),
            dataType: 'json',
            success: function (res) {
                if (res.status === 'success' || res.success == 1) {
                    toastr.success(res.message || "Success", res.message_header || "Per Diem Network");
                    setTimeout(function () {
                        window.location.href = res.redirect;
                    }, 1000);
                } else {
                    isSubmitting = false;
                    btn.prop('disabled', false).text(isUpdate ? "Update Network" : "Save Network");
                    
                    if (typeof res.errors === 'object') {
                        $.each(res.errors, function (field, msg) {
                            toastr.error(msg, "Validation Error");
                        });
                    } else {
                        toastr.error(res.message || "An error occurred", res.message_header || "Error");
                    }
                }
            },
            error: function () {
                isSubmitting = false;
                btn.prop('disabled', false).text(isUpdate ? "Update Network" : "Save Network");
                toastr.error("An unexpected error occurred.", "Error");
            }
        });
    }

    $("#submit-btn, #submit-btn-update").on('click', function (e) {
        e.preventDefault();
        let btn = $(this);
        
        if (isSubmitting) return;
        
        isSubmitting = true;
        btn.prop('disabled', true).text("Processing...");

        if (logoDropzone.getQueuedFiles().length > 0) {
            logoDropzone.processQueue();
        } else {
            submitFormData();
        }
    });

    form.on('submit', function (e) {
        e.preventDefault();
        if (!isSubmitting) {
            $("#submit-btn, #submit-btn-update").first().click();
        }
    });
});
